<template>
 <view :class="['screen','page-'+page, { 'has-tabs': isTab, 'bottom-space': bottomSpace, mine: page==='mine', 'order-background': ['checkout','order-detail'].includes(page) }]">
  <view v-if="!isTab" class="nav" :style="nativeNavStyle"><text class="back" :style="nativeBackStyle" @click="back">‹</text><text>{{ title }}</text>
<!-- #ifdef H5 -->
<view class="capsule"><text>•••</text><text>━</text><text>⊙</text></view>
<!-- #endif -->
</view>
<view v-if="loading" class="loading">加载中…</view><view v-if="error" class="error-bar"><text>{{error}}</text><button class="error-retry" @click="refresh">重新加载</button></view>
  <template v-if="page==='home'">
   <view class="hero-wrap"><image :src="config.heroTop||'/static/brand/hero-top-jimeili-v2.jpg'" mode="scaleToFill" class="hero-top-art"/><view class="hero-middle-slot"><image :src="config.homeImage||'/static/brand/hero-middle.jpg'" mode="aspectFill" class="hero-middle-image"/></view><view class="hero-bottom-art"><image :src="config.heroBottom||'/static/brand/hero-bottom-v2.jpg'" mode="scaleToFill"/></view><view class="welcome-live"><view>美容 · 疗愈</view><view>静享肌肤时光</view><text>/ {{config.name||'暨美丽'}} 欢迎您的到来 /</text></view></view>
   <view class="shortcuts"><view v-for="s in shortcuts" :key="s.label" class="shortcut" @click="open(s.page,s.query)"><view class="shortcut-icon"><image :src="'/static/reference/shortcut-'+s.asset+'.png'" mode="aspectFit"/></view>{{ s.label }}</view></view>
   <view class="entry-grid"><view class="entry-left" @click="open('appointments')"><image src="/static/assets/booking.jpg" mode="widthFix"/></view><view class="entry-right"><image src="/static/assets/stores-entry.jpg" mode="widthFix" @click="open('stores')"/><image src="/static/assets/vip-entry.jpg" mode="widthFix" @click="open('activities')"/></view></view><image src="/static/assets/alliance-entry.jpg" class="alliance-entry" mode="widthFix" @click="open('alliances')"/><view v-for="module in homeModules" :key="module.id" class="home-module home-card" @click="homeModuleClick(module)"><image :src="module.image" mode="widthFix" class="wide-img"/><view class="card-copy"><view class="title">{{module.title}}</view><view v-if="module.subtitle" class="muted">{{module.subtitle}}</view><view v-if="module.description" class="description">{{module.description}}</view></view></view>
   <view v-for="s in stores" :key="s.id" class="home-card store-card" @click="open('stores')"><view class="store-visual"><image :src="s.image||config.storeDefaultImage||'/static/brand/store-cover-jimeili-v2.jpg'" class="wide-img" mode="widthFix"/></view><view class="card-copy"><view class="between"><text class="title">{{s.name}}</text><text class="pill">进入门店</text></view><view class="description">{{s.contact}}<view>门店地址：{{s.address}}</view></view></view></view>
<view class="home-section-heading home-category-heading"><image :src="config.serviceHeading||config.projectPromo||'/static/assets/service-heading.jpg'" mode="widthFix"/></view><view v-for="serviceProduct in featuredProducts" :key="serviceProduct.id" class="home-card home-product" :data-product-id="serviceProduct.id" @click="productPage(serviceProduct)"><image :src="serviceProduct.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img" @error="imageError"/><view class="card-copy"><view class="title">{{serviceProduct.name}}</view><view class="price-lines"><text class="price">单次 ¥{{money(serviceProduct.price)}}</text><text v-if="serviceProduct.coursePrice!==undefined&&serviceProduct.coursePrice!==null" class="muted">疗程 ¥{{money(serviceProduct.coursePrice)}}</text></view><text class="pill product-buy">去抢购</text></view></view><view class="home-section-heading home-category-heading"><image :src="config.productHeading||'/static/assets/product-heading.jpg'" mode="widthFix"/></view><view v-for="goodsProduct in goodsProducts" :key="goodsProduct.id" class="home-card home-product" :data-product-id="goodsProduct.id" @click="productPage(goodsProduct)"><image :src="goodsProduct.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img" @error="imageError"/><view class="card-copy"><view class="title">{{goodsProduct.name}}</view><view class="price-lines"><text class="price">单件 ¥{{money(goodsProduct.price)}}</text><text v-if="goodsProduct.coursePrice!==undefined&&goodsProduct.coursePrice!==null" class="muted">疗程 ¥{{money(goodsProduct.coursePrice)}}</text></view><text class="pill product-buy">去抢购</text></view></view><image :src="config.brand||'/static/brand/brand-jimeili.png'" class="brand-footer" mode="widthFix"/>
  </template>
  <template v-else-if="page==='mall'"><view class="nav mall-nav" :style="nativeNavStyle"><view class="mall-home" @click="switchTab('home')"><image src="/static/icons/mall-home.svg" mode="aspectFit"/></view><text>商城</text><!-- #ifdef H5 --><view class="capsule"><text>•••</text><text>━</text><text>⊙</text></view><!-- #endif --></view><view class="mall-shell"><view class="mall-categories"><view v-for="c in mallCategories" :key="c.id" :class="['mall-category',{active:mallCategory===c.id}]" @click="mallCategory=c.id">{{c.name}}</view></view><view class="mall-content"><image class="mall-banner" :src="selectedMallCategoryName.includes('优选')?(config.productHeading||'/static/assets/product-heading.jpg'):(config.serviceHeading||config.projectPromo||config.welcome||'/static/assets/service-heading.jpg')" mode="widthFix"/><view class="mall-heading">{{selectedMallCategoryName}}</view><view class="mall-product-list"><view v-for="p in mallProducts" :key="p.id" class="mall-product-row" @click="productPage(p)"><image class="mall-product-thumb" :src="p.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view class="mall-product-main"><view class="mall-product-name">{{p.name}}</view><view class="mall-store-tag">门店</view><view class="mall-price-row"><text class="mall-price">¥{{money(p.price)}}</text><text v-if="p.coursePrice!==undefined&&p.coursePrice!==null" class="mall-course-price">疗程 ¥{{money(p.coursePrice)}}</text></view></view><text class="pill mall-buy">去购买</text></view></view><view v-if="!mallProducts.length" class="mall-empty">暂无商品</view></view></view></template>
  <template v-else-if="page==='product' && product"><view v-if="isPackage" class="vip-product-cover"><image :src="product.image||'/static/reference/shortcut-vip.svg'" mode="aspectFit"/><view>{{product.name}}</view><text>暨美丽 · 专属服务套餐</text></view><view v-else class="product-cover-wrap"><image :src="product.image||product.detailImage||'/static/assets/product-placeholder.jpg'" class="product-cover" mode="aspectFit" @error="imageError"/></view><view v-if="product.gallery&&product.gallery.length" class="product-gallery"><image v-for="url in product.gallery" :key="url" :src="url||product.detailImage||product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/></view><view class="product-info"><view class="title">{{product.name}}</view><view v-if="product.subtitle" class="muted product-subtitle">{{product.subtitle}}</view><view v-if="product.brand" class="muted">品牌：{{product.brand}}</view><template v-if="product.trialOnly"><text v-if="product.referencePrice!=null" class="price-detail">价值 ¥{{money(product.referencePrice)}}</text><view class="description">体验卡领取后免费预约</view></template><text v-else class="price-detail">会员价 {{money(unitPrice)}}元</text></view><view class="stock"><text>已售：{{product.sold}}件</text><text>库存：{{product.stock}}件</text></view><package-picker v-if="isPackage" v-model="packageSelection" :plans="product.packagePlans" :disabled="busy||loading"/><view v-else class="section-title">商品详情</view><view v-if="!isPackage" class="detail-art-wrap"><image :src="product.detailImage||product.image||'/static/assets/product-placeholder.jpg'" class="detail-art" mode="widthFix" @error="imageError"/></view><view v-if="product.description" class="card rules">{{product.description}}</view><view class="bottom-actions"><view class="mini-action" @click="switchTab('home')"><image src="/static/reference/tab-home.png" mode="aspectFit"/>首页</view>
<!-- #ifdef MP-WEIXIN -->
<button class="mini-action" open-type="contact" session-from="product" show-message-card><image src="/static/reference/customer-service.png" mode="aspectFit"/>客服</button>
<button class="mini-action" open-type="share"><image src="/static/reference/menu-shares.png" mode="aspectFit"/>分享</button>
<!-- #endif -->
<!-- #ifdef H5 -->
<button class="mini-action" @click="contact"><image src="/static/reference/customer-service.png" mode="aspectFit"/>客服</button>
<!-- #endif --><button v-if="product.trialOnly" class="primary" @click="open('gifts','?type=trial')">领取体验卡并预约</button><button v-else class="primary" :disabled="busy||loading||!!error" @click="isPackage?checkoutPackage():sheet=true">{{isPackage?'确认方案并购买':'立即购买'}}</button></view></template>
  <template v-else-if="page==='stores'"><view v-for="s in stores" :key="s.id" class="home-card store-page-card"><view class="store-visual"><image :src="s.image||config.storeDefaultImage||'/static/brand/store-cover-jimeili-v2.jpg'" class="wide-img" mode="widthFix"/></view><view class="store-page-copy"><view class="title">{{s.name}}</view><view class="description">{{s.contact}}<view>门店地址：{{s.address}}</view><view v-if="s.phone">联系电话：<text class="link" @click="call(s.phone)">{{s.phone}}</text></view><view v-if="s.hours">营业时间：{{s.hours}}</view></view></view></view><view v-if="!stores.length" class="empty">暂无门店</view><view v-else class="empty">已经到底了～</view></template>
  <template v-else-if="page==='gifts'">
    <view class="gift-page-intro"><view v-if="!hasGiftClaim" class="gift-selection-hint">~可免费领取任意{{config.maxGifts||3}}件~</view><template v-else><view class="gift-page-title">{{giftType==='trial'?'体验卡已领取':'贵宾卡已领取'}}</view><view class="description">{{giftType==='trial'?'每个项目可预约到店体验一次':'服务礼品可预约使用，实物礼品请到店领取'}}</view></template></view>
    <template v-if="!hasGiftClaim">
      <view v-if="!giftEligible" class="notice gift-shortage">贵宾卡仅限受邀会员领取</view>
      <view v-if="giftProducts.length>0&&giftProducts.length<config.maxGifts" class="notice gift-shortage">当前可领取{{giftProducts.length}}项，满{{config.maxGifts}}项后可领取，请联系门店</view>
      <view v-if="!giftProducts.length&&!loading" class="empty">暂无数据～</view>
      <view v-else class="grid"><view v-for="p in giftProducts" :key="p.id" class="gift-card" @click="productPage(p)"><image :src="p.image||'/static/assets/product-placeholder.jpg'" :mode="p.trialOnly?'aspectFit':'aspectFill'" :class="{'trial-poster':p.trialOnly}"/><view class="gift-copy"><view class="gift-name">{{p.name}}</view><view v-if="p.subtitle" class="gift-spec muted">{{p.subtitle}}</view><view v-if="p.referencePrice!=null" class="gift-value">价值 ¥{{money(p.referencePrice)}}</view><view class="between gift-actions"><button class="outline" :disabled="busy||loading" :style="selectedGifts.includes(p.id)?'background:#c98bdd;color:#fff':''" @click.stop="selectGift(p.id)">{{selectedGifts.includes(p.id)?'已选':'选择'}}</button><text class="muted">{{giftType==='trial'?'免费体验':'免费领取'}}</text></view></view></view></view>
    </template>
    <view v-if="receivedGifts.length" class="claimed-gifts"><view class="section-title">已领取的{{giftType==='trial'?'体验项目':'礼品'}}</view><view v-for="p in receivedGifts" :key="p.claimId+'-'+p.id" class="card claimed-gift"><image :src="p.image" mode="aspectFit"/><view class="claimed-gift-copy"><view>{{p.name}}</view><view v-if="p.subtitle||p.referencePrice!=null" class="gift-spec muted">{{p.subtitle}}<text v-if="p.referencePrice!=null"> · 价值 ¥{{money(p.referencePrice)}}</text></view><text class="muted">{{p.useStatus==='completed'?'已使用':p.useStatus==='booked'?'已预约':p.kind==='service'?'待预约使用':'待到店领取'}}</text><view class="claim-buttons"><button class="outline" @click="productPage(p)">查看详情</button><button v-if="p.kind==='service'&&p.useStatus==='available'" class="pill" :disabled="busy||loading||!!error" @click="startGiftBooking(p)">预约使用</button><button v-else-if="p.useStatus==='booked'" class="outline" @click="open('appointments','?tab=booked')">查看预约</button></view></view></view></view>
    <view v-if="!hasGiftClaim" class="bottom-actions gift-selection-footer"><button class="primary" :disabled="busy||loading||!!error||!giftEligible" @click="claim">{{busy?'领取中…':'选择商品'}}</button></view>
  </template>
  <template v-else-if="page==='login'"><view class="login-body"><view class="login-brand"><image :src="config.brandLogo||'/static/brand/logo-jimeili.png'" class="login-logo" mode="aspectFit"/><view class="title">欢迎来到{{config.name||'暨美丽'}}</view><view class="login-subtitle">登录后领取体验卡、预约到店服务</view></view><view class="account-login"><button class="primary wechat-login" :disabled="busy||loading" @click="wechatLogin">{{busy?'登录中…':'微信一键登录'}}</button><view v-if="!nativeDevice" class="login-web-note">请在微信小程序内使用微信登录</view></view><view class="agreement"><button class="agreement-toggle" :aria-label="agreed?'取消同意协议':'同意协议'" @click="agreed=!agreed"><text :class="['check',{on:agreed}]">{{agreed?'✓':''}}</text></button><view class="agreement-copy"><text @click="agreed=!agreed">我已阅读并同意</text><text class="link" @click="open('legal','?type=agreement')">《用户服务协议》</text>与<text class="link" @click="open('legal','?type=privacy')">《隐私政策》</text><view class="agreement-note">首次微信登录将自动创建会员</view></view></view><button class="login-skip" @click="switchTab('home')">暂不登录，先逛逛 ›</button></view></template>
  <template v-else-if="page==='profile'"><view class="form"><view class="field" style="height:194rpx"><label>头像<text class="required">*</text></label><view class="avatar-editor" @click="chooseAvatar"><image :src="form.avatar||me.avatar||'/static/assets/avatar.png'" mode="aspectFit"/><text class="avatar-remove" @click.stop="removeAvatar">×</text></view></view><view class="field"><label>姓名<text class="required">*</text></label><input v-model="form.name" :disabled="loading" placeholder="请输入姓名" maxlength="40"/></view><view class="field" style="border:0"><label>性别<text class="required">*</text></label><text @click="!loading&&(form.gender='male')"><text :class="['check',{on:form.gender==='male'}]"/>先生</text><text style="margin-left:80rpx" @click="!loading&&(form.gender='female')"><text :class="['check',{on:form.gender==='female'}]"/>女士</text></view><button class="primary" :disabled="busy||loading" @click="saveProfile">保存信息</button></view></template>
<template v-else-if="page==='mine'"><view class="profile-head" @click="open(me.id?'profile':'login')"><image :src="me.avatar||'/static/assets/avatar.png'" class="profile-avatar"/><view><view class="title">{{me.id?(me.name||'微信会员'):'点击登录'}}</view><view class="muted" style="margin-top:14rpx">{{me.id?(me.phone?'手机号 '+me.phone:'完善个人信息'):'领取体验卡 · 预约到店服务'}}</view></view><image class="profile-share-icon" src="/static/reference/profile-code.png" @click.stop="open('share')"/></view><view class="stats mine-stats"><view class="stat" @click="open('points')"><view class="stat-copy"><view class="muted">我的积分</view><view>{{me.id?(me.points||0)+'个':'—'}}</view></view><image class="stat-icon" src="/static/reference/points.png" mode="aspectFit"/></view><view class="stat" @click="open('earnings')"><view class="stat-copy"><view class="muted">累计收益</view><view>{{me.id?earningsTotal+'元':'—'}}</view></view><image class="stat-icon" src="/static/reference/earnings.png" mode="aspectFit"/></view></view><view class="vip-pool"><view class="pool-copy"><view>VIP积分池</view><text class="pool-note">开放后可在此查看专属积分</text></view><view class="pool-number"><image src="/static/reference/vip-pool-outline.svg" mode="aspectFit"/><text>暂未开放</text></view></view><view v-for="(group,groupIndex) in menuGroups" :key="groupIndex" class="card menu"><template v-for="menuItem in group" :key="menuItem[1]"><button v-if="menuItem[1]==='contact'" class="menu-item menu-contact" open-type="contact" session-from="mine" @click="!nativeDevice&&contact()"><image class="menu-icon-image" :src="menuIcon(menuItem[1])" mode="aspectFit"/><text>{{menuItem[0]}}</text><text class="chevron">›</text></button><view v-else class="menu-item" @click="menuClick(menuItem)"><image class="menu-icon-image" :src="menuIcon(menuItem[1])" mode="aspectFit"/><text>{{menuItem[0]}}</text><text class="chevron">›</text></view></template></view></template>
<template v-else-if="page==='discover'"><view class="discover-head discover-points-head" :style="nativeDevice?{paddingTop:(statusBar+24)+'px'}:{}"><view class="title">积分商城</view><image class="points-banner" :src="config.pointsBanner||'/static/assets/points-banner.jpg'" mode="widthFix"/></view><view class="discover-links"><view @click="open('sign')"><image class="discover-icon" src="/static/reference/daily.png" mode="aspectFit"/><text>每日签到</text></view><view @click="open('points')"><image class="discover-icon" src="/static/reference/income.png" mode="aspectFit"/><text>积分收入</text></view><view @click="open('redemptions')"><image class="discover-icon" src="/static/reference/redeem.png" mode="aspectFit"/><text>兑换记录</text></view></view><view v-for="r in rows" :key="r.id" class="card reward-card"><image v-if="r.image" :src="r.image" mode="aspectFit"/><view class="between"><view><view class="title">{{r.name}}</view><view class="muted">{{r.points}}积分</view></view><button class="pill" @click="redeemReward(r)">兑换</button></view></view><view v-if="!rows.length" class="empty">暂无数据~</view></template>
  <template v-else-if="page==='addresses'"><view v-for="a in rows" :key="a.id" class="card" @click="open('address-edit','?id='+a.id)"><view class="between"><text>{{a.name}}　{{a.phone}}</text><text class="link">编辑</text></view><view class="description">{{a.city}} {{a.detail}}</view><view class="between" style="margin-top:20rpx"><text class="tag" v-if="a.isDefault">默认地址</text><text class="muted" @click.stop="deleteAddress(a)">删除</text></view></view><view v-if="!rows.length" class="empty">暂无收货地址，请先添加</view><view class="bottom-actions"><button class="primary" @click="open('address-edit')">添加地址</button></view></template>
  <template v-else-if="page==='address-edit'"><view class="form"><view v-for="f in addressFields" :key="f.key" class="field"><label>{{f.label}}<text class="required">*</text></label><template v-if="f.key==='city'">
<!-- #ifdef MP-WEIXIN -->
<picker mode="region" :disabled="loading" :value="regionValue" @change="form.city=$event.detail.value.join(' ')"><text :style="{color:form.city?'#17212c':'#c7c7c7'}">{{form.city||'选择收件城市'}}</text></picker>
<!-- #endif -->
<!-- #ifdef H5 -->
<input v-model="form.city" :disabled="loading" placeholder="输入省 / 市 / 区"/>
<!-- #endif -->
</template><input v-else v-model="form[f.key]" :disabled="loading" :type="f.key==='phone'?'number':'text'" :maxlength="f.key==='phone'?11:200" :placeholder="f.placeholder"/></view><view class="field" style="border:0"><label>设为默认</label><text @click="!loading&&(form.isDefault=!form.isDefault)"><text :class="['check',{on:form.isDefault}]"/>选中默认</text></view><button class="primary" :disabled="busy||loading" @click="saveAddress">保存地址</button></view></template>
  <template v-else-if="['product','checkout'].includes(page)&&!product"><view v-if="!loading" class="empty">商品不存在或已下架<button class="outline" @click="switchTab('mall')">返回商城</button></view></template>
  <template v-else-if="page==='checkout'&&product"><view class="card order-product"><image :src="product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view>{{product.name}}</view><view style="color:#ff3a13;margin-top:15rpx">￥{{money(unitPrice)}} / 件</view><view class="muted">购买规格：{{selectedPackagePlan?.name||selectedSku?.name||(spec==='course'?'1疗程':product.kind==='goods'?'1件':'1次')}} × {{quantity}}件</view></view></view><package-picker v-if="isPackage" v-model="packageSelection" :plans="product.packagePlans" :disabled="busy||loading"/><view class="card selected-store"><view class="between"><text>服务门店<text class="required">*</text></text><picker :disabled="loading||!stores.length" :range="stores" range-key="name" :value="storeIndex" @change="storeIndex=Number($event.detail.value)">{{chosenStore.name||'选择门店'}} ›</picker></view><view v-if="chosenStore.id" class="description">门店地址：{{chosenStore.address||'地址待门店补充'}}<view v-if="chosenStore.phone">联系电话：<text class="link" @click="call(chosenStore.phone)">{{chosenStore.phone}}</text></view></view><view v-else class="description">{{stores.length?'请重新选择服务门店':'暂无可选门店，请联系商家'}}</view></view><view v-if="product.kind==='goods'" class="card"><view class="between"><text>收货地址<text class="required">*</text></text><text class="link" @click="open('addresses')">管理地址</text></view><picker v-if="addresses.length" :range="addresses" range-key="detail" :value="addressIndex" @change="addressIndex=Number($event.detail.value)"><view class="description">{{chosenAddress.name}} {{chosenAddress.city}} {{chosenAddress.detail}} ›</view></picker><view v-else class="description" @click="open('address-edit')">{{loading?'正在读取收货地址…':'请先添加收货地址 ›'}}</view></view><view class="card"><view class="order-line"><text>商品金额</text><text>{{money(total)}}元</text></view><view class="order-line"><text>订单金额</text><text style="color:#b96ee0">{{total}}元</text></view></view><view v-if="purchaseIncomeRule" class="card"><view class="title">套餐静态收益规则</view><view class="description">{{purchaseIncomeText}}</view></view><view class="card"><input v-model="form.message" placeholder="请在这里输入您的留言" maxlength="200"/></view><view class="bottom-actions"><text style="flex:1">应付金额：<text style="color:#ff3a13">￥{{total}}</text></text><button class="primary" style="max-width:300rpx;height:74rpx" :disabled="busy||loading" @click="createOrder">{{isPackage?'提交套餐订单':'立即付款'}}</button></view></template>
  <template v-else-if="page==='orders'"><view class="tabs"><text v-for="(t,i) in orderTabs" :key="t" :class="{selected:tab===i}" @click="tab=i">{{t}}</text></view><view v-for="o in filteredRows" :key="o.id" class="card"><view class="between" style="font-size:25rpx;margin:10rpx 10rpx 12rpx"><text>{{date(o.createdAt)}}</text><text :style="{color:o.status==='pending'?'red':'#ad68d3'}">{{statusText(o.status)}}</text></view><view class="order-product" @click="open('order-detail','?id='+o.id)"><image :src="o.product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view>{{o.product.name}}</view><view class="muted">购买 {{o.package?.planName||o.product.selectedSku?.name||(o.spec==='course'?'1疗程':o.spec==='single'?'1次':'')}} {{o.quantity}}件</view><text class="price" style="font-weight:400;font-size:28rpx">￥{{money(o.total)}}</text></view></view><view class="order-buttons"><text style="font-size:23rpx;margin-right:auto">订单应付<text class="price" style="font-size:25rpx">{{o.total}}</text>元</text><button v-if="o.status==='pending'" @click="cancelOrder(o)">取消订单</button><button @click="open('order-detail','?id='+o.id)">订单详情</button><button v-if="o.status==='pending'" class="pay" @click="pay(o)">联系门店付款</button></view></view><view class="empty">{{filteredRows.length?'已经到底了～':'暂无数据～'}}</view></template>
  <template v-else-if="page==='order-detail'&&order"><view class="card"><view class="title">{{statusText(order.status)}}</view><view class="description">{{order.status==='pending'?'下单2小时内未支付自动取消~':order.paymentMode==='offline'?'门店已确认线下收款':order.paymentStatus==='paid'?'微信支付已完成':order.status==='aftersale'?(order.refundNote||'售后退款处理中'):'感谢您的惠顾'}}</view></view><view class="card"><view class="title" style="font-weight:400">服务门店信息</view><view class="notice order-store-note">以下是到店服务门店信息，不是收货地址</view><view class="order-line"><text>门店名称</text><text>{{orderStore.name||'原门店信息已变更'}}</text></view><view class="order-line"><text>门店位置</text><text>{{orderStore.address||'请联系商家确认门店地址'}}</text></view><view class="order-line"><text>联系人</text><text>{{orderStore.phone}} {{orderStore.contact}}</text></view></view><view class="card order-product"><image :src="order.product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view>{{order.product.name}}</view><view class="muted">规格：{{order.package?.planName||order.product.selectedSku?.name||(order.spec==='course'?'1疗程':order.spec==='single'?'1次':'')}}<view>￥{{money(order.price)}}× {{order.quantity}}件</view></view><text class="price" style="font-size:28rpx;font-weight:400">￥{{money(order.total)}}</text></view></view><view class="card"><view class="order-line"><text>商品金额</text><text>{{money(order.total)}}元</text></view><view class="order-line"><text>应付金额</text><text>{{money(order.total)}}元</text></view></view><view v-if="order.package" class="card package-entitlements"><view class="title">{{order.package.planName}} · 服务项目</view><view v-for="item in order.package.services" :key="item.id" class="entitlement-row"><view><view>{{item.name}}</view><view class="muted">共{{item.total}}次 · 已使用{{item.used}}次<text v-if="order.status==='ready'"> · 可预约{{packageRemaining(order,item)}}次</text></view></view><button v-if="order.status==='ready'&&packageRemaining(order,item)>0" class="pill" @click="openPackageBooking(order,item)">预约</button></view><view v-if="order.status==='pending'" class="description">请联系所选门店确认付款，确认收款后可预约各项目。</view></view><view v-if="order.address" class="card"><view>收货信息</view><view class="description">{{order.address.name}} {{order.address.phone}}<view>{{order.address.city}} {{order.address.detail}}</view></view></view><view class="card"><view>订单信息</view><view class="order-line"><text>订单编号</text><text @click="copy(order.number)">{{order.number}} [复制]</text></view><view class="order-line"><text>下单时间</text><text>{{date(order.createdAt)}}</text></view><view v-if="order.tracking" class="card"><view>物流 / 取货信息</view><view class="description">{{order.tracking}}</view></view></view><view class="bottom-actions"><button class="outline" @click="open('orders')">返回列表</button><button v-if="order.status==='pending'" class="outline" @click="cancelOrder(order)">取消订单</button><button v-if="order.status==='pending'" class="pill" @click="pay(order)">联系门店付款</button><button v-if="order.status==='ready'" class="pill" @click="open('appointments')">预约服务</button></view></template>
  <template v-else-if="page==='appointments'">
    <view class="tabs"><text v-for="(t,i) in ['待预约','已预约','已完成']" :key="t" :class="{selected:tab===i}" @click="tab=i">{{t}}</text></view>
    <view v-for="a in filteredRows" :key="a.id" class="card"><view class="title">{{a.name||(a.product&&a.product.name)}}</view><view class="description">{{tab===0?(a.entitlementId?'套餐项目 · 还可预约'+a.remaining+'次':'已购买服务，可选择时间预约'):a.date+' '+a.time}}</view><view v-if="a.staff?.name" class="description">服务员工：{{a.staff.name}} · {{a.durationMinutes||60}}分钟</view><view class="description appointment-store">服务门店：{{recordStore(a).name||'原门店信息已变更'}}<view>门店地址：{{recordStore(a).address||'请联系商家确认'}}</view></view><button v-if="tab===0" class="pill" style="margin-top:20rpx" @click="startOrderBooking(a)">立即预约</button></view>
    <view v-if="tab===0" v-for="p in availableClaimGifts" :key="p.claimId+'-'+p.id" class="card"><view class="title">{{p.name}}</view><view v-if="p.subtitle||p.referencePrice!=null" class="description">{{p.subtitle}}<text v-if="p.referencePrice!=null"> · 价值 ¥{{money(p.referencePrice)}}</text></view><view class="description">{{p.claimType==='trial'?'体验卡项目':'贵宾卡服务'}}，可预约到店使用</view><button class="pill" @click="startGiftBooking(p)">预约使用</button></view>
    <view v-if="!filteredRows.length&&!(tab===0&&availableClaimGifts.length)&&!loading" class="empty">{{tab===0?'暂无待预约项目，可先领取体验卡':tab===1?'暂无已预约记录':'暂无已完成记录'}}<button v-if="tab===0" class="outline" @click="open('gifts','?type=trial')">领取体验卡</button></view>
    <view class="bottom-actions" style="justify-content:center"><button class="pill" style="padding:20rpx 38rpx" :disabled="busy||loading||!!error||availableBookingCount===0" @click="startBooking">我要预约（还可预约{{availableBookingCount}}次）</button></view>
  </template>
  <template v-else-if="page==='booking'">
    <view v-if="bookingProduct" class="card"><view class="title">{{bookingProduct.name}}</view><view v-if="!order?.package&&(bookingProduct.subtitle||bookingProduct.referencePrice!=null)" class="description">{{bookingProduct.subtitle}}<text v-if="bookingProduct.referencePrice!=null"> · 价值 ¥{{money(bookingProduct.referencePrice)}}</text></view><view class="description">{{query.claimId?(bookingClaim.type==='vip'?'贵宾卡服务':'体验卡项目，无需支付'):order?.package?order.product.name+' · 本次预约使用1次':'已购买服务'}}</view></view>
    <view v-if="!loading&&!bookingAvailable" class="notice gift-shortage">该项目暂不可预约，请在我的预约中查看使用状态<button class="outline" @click="open('appointments')">查看我的预约</button></view>
    <view class="card selected-store"><view class="between"><text>服务门店</text><picker v-if="query.claimId" :disabled="loading||!bookingAvailable||!stores.length" :range="stores" range-key="name" :value="storeIndex" @change="storeIndex=Number($event.detail.value)">{{chosenStore.name||'选择门店'}} ›</picker><text v-else>{{bookingStore.name||'原门店信息已变更'}}</text></view><view class="description">门店地址：{{bookingStore.address||'请联系商家确认'}}<view v-if="bookingStore.phone">联系电话：<text class="link" @click="call(bookingStore.phone)">{{bookingStore.phone}}</text></view></view><view v-if="!loading&&!bookingStoreEnabled" class="description">{{stores.length?'请选择营业中的门店，原订单门店不可预约时请联系商家':'暂无可预约门店，请联系商家'}}</view></view>
    <view class="form"><BookingAvailability :source="bookingSource" :disabled="loading||!bookingAvailable||!bookingStoreEnabled" :today="today" :refresh-key="bookingRefresh" @selection="setBookingSelection"/><button class="primary" :disabled="busy||loading||!!error||!bookingAvailable||!bookingStoreEnabled||!bookingReady" @click="book">{{busy?'预约中…':'确认预约'}}</button></view>
  </template>
  <template v-else-if="page==='share'"><view class="share-page"><view class="share-hero-frame"><image src="/static/assets/share-art.jpg" class="share-hero-art" mode="widthFix"/></view><view class="share-card-frame"><image src="/static/reference/share-card.png" mode="scaleToFill"/><view class="share-qr"><image v-if="shareImage||config.customerQr" :src="shareImage||config.customerQr" class="share-qr-image" mode="aspectFit" show-menu-by-longpress @longpress="handleShareLongpress" @click="previewShare"/><view v-else class="share-empty" @click="!loading&&(me.id?refresh():open('login'))">{{loading?'分享码加载中…':me.id?'分享码暂未生成，点击重试':'点击登录后查看分享码'}}</view></view></view><view class="share-code-actions"><!-- #ifdef MP-WEIXIN --><button open-type="share">转发给好友</button><!-- #endif --><button @click="copy(inviteCode)">复制邀请码</button><button @click="previewShare">查看分享码</button></view></view></template>
  <template v-else-if="page==='about'"><image :src="config.brandLogo||'/static/brand/logo-jimeili.png'" class="about-logo" mode="aspectFit"/><view class="about-title">{{config.name||'暨美丽'}}</view><view class="card" style="margin:0 78rpx;padding:38rpx"><view class="field"><label style="width:auto;flex:1">小程序版本</label>{{appVersion}}</view><view class="field" @click="open('legal','?type=agreement')"><label style="width:auto;flex:1">用户服务协议</label>点击查看</view><view class="field" style="border:0" @click="open('legal','?type=privacy')"><label style="width:auto;flex:1">用户隐私政策</label>点击查看</view></view></template>
  <template v-else-if="page==='legal'"><view class="legal-page"><view class="legal-title">{{legalTitle}}</view><view v-if="query.type!=='pointsRules'" class="legal-date">生效日期：2026年09月29日</view><view class="card rules">{{config[query.type]}}</view></view></template>
  <template v-else-if="page==='earnings'"><IncomeDashboard :records="rows" :summary="incomeSummary" :loading="loading"/></template>
  <template v-else-if="page==='points'"><view class="purple-top"><view class="big-number">{{me.points||0}}</view><view>我的积分</view></view><view class="stats points-stats"><view :class="['stat',{selected:tab===0}]" @click="tab=0"><view class="stat-copy"><view class="muted">积分收入</view><view>{{pointsEarned}}个</view></view><image class="stat-icon" src="/static/reference/points.png" mode="aspectFit"/></view><view :class="['stat',{selected:tab===1}]" @click="tab=1"><view class="stat-copy"><view class="muted">积分支出</view><view>{{pointsSpent}}个</view></view><image class="stat-icon" src="/static/reference/points.png" mode="aspectFit"/></view></view><view v-for="r in pointRows" :key="r.id" class="card ledger-card"><view>{{r.name}}</view><view class="between muted"><text>{{date(r.createdAt)}}</text><text class="link">{{r.amount>0?'+':''}}{{r.amount}}积分</text></view></view><view v-if="!pointRows.length" class="empty">暂无数据～</view></template><template v-else-if="page==='sign'"><view class="purple-top sign-top"><text class="rules-entry" @click="open('legal','?type=pointsRules')">ⓘ 积分规则</text><view class="big-number">{{me.points||0}}</view><view>我的积分</view></view><view class="card points-card"><view class="between"><view class="sign-summary">已连续签到<view class="sign-streak"><text class="link">{{me.streak||0}}</text>天</view></view><button class="pill" :disabled="me.lastSign===today" @click="signIn">{{me.lastSign===today?'今日已签到':'立即签到+'+(config.signPoints||100)}}</button></view><view class="days"><view v-for="(dayLabel,dayIndex) in signDays" :key="dayLabel"><text>+{{config.signPoints||100}}</text><view class="day-star"><image :src="dayIndex<signProgress?'/static/reference/sign-on.png':'/static/reference/sign-off.png'" mode="aspectFit"/></view></view></view><view class="timeline"><text v-for="i in 7" :key="i" :class="{done:i<=signProgress}"/></view></view></template><template v-else-if="page==='redemptions'"><view v-for="r in rows" :key="r.id" class="card redemption-card"><view class="between"><text class="title">{{r.name}}</text><text class="tag">已兑换</text></view><view class="redemption-meta"><text>{{date(r.createdAt)}}</text><text>{{r.points}}积分</text></view></view><view v-if="!rows.length" class="empty">暂无兑换记录~</view></template><template v-else-if="page==='activities'"><view v-if="vipProducts.length" class="vip-activity-list"><view class="section-title">VIP服务套餐</view><view v-for="item in vipProducts" :key="item.id" class="card vip-activity-row" @click="productPage(item)"><image :src="item.image" mode="aspectFit"/><view><view class="title">{{item.name}}</view><view class="description">{{item.subtitle}}</view><view class="price">¥{{money(item.price)}}</view></view><text class="link">查看 ›</text></view></view><view v-for="r in rows" :key="r.id" class="card activity-card"><image v-if="r.image" :src="r.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img"/><view class="title">{{r.name}}</view><view class="description">{{r.description||'活动详情请咨询门店'}}</view><view v-if="r.startAt||r.endAt" class="muted">活动时间：{{r.startAt||'即日起'}} 至 {{r.endAt||'另行通知'}}</view><button v-if="r.productId&&activityProduct(r)" class="primary activity-button" @click="productPage(activityProduct(r))">查看商品并购买</button></view><view v-if="!rows.length&&!vipProducts.length" class="empty">暂无数据～</view></template><template v-else><view v-for="r in rows" :key="r.id" class="card"><image v-if="r.image" :src="r.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img"/><view class="title">{{r.name}}</view><view class="description">{{r.description||date(r.createdAt)}}</view><text v-if="r.phone" class="link" @click="call(r.phone)">{{r.phone}}</text></view><view v-if="!rows.length" class="empty">暂无数据～</view></template>
  <view v-if="isTab" class="tabbar"><view v-for="t in mainTabs" :key="t.page" :class="['tabitem',{active:page===t.page}]" @click="switchTab(t.page)"><image :src="tabIcon(t.page)" mode="aspectFit"/>{{t.name}}</view></view>
  <view v-if="sheet&&product" class="overlay" @click="sheet=false"><view class="sheet" @click.stop><text class="close" @click="sheet=false">×</text><view class="sheet-head row"><image :src="product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view style="font-size:34rpx">{{product.name}}</view><view style="color:#df25ff;margin:18rpx 0">￥{{unitPrice}}</view><text class="muted">已选：{{selectedSku?.name||(spec==='course'?'1疗程':product.kind==='goods'?'1件':'1次')}}，{{quantity}}件</text></view></view><view>选择商品规格</view><view v-if="product.skus&&product.skus.length" class="specs sku-specs"><text v-for="sku in product.skus" :key="sku.id" :class="['spec',{selected:sku.id===skuId,disabled:sku.enabled===false||sku.stock<1}]" @click="sku.enabled!==false&&sku.stock>0&&(skuId=sku.id)">{{sku.name}} ¥{{money(sku.price)}}</text></view><view v-else class="specs"><text :class="['spec',{selected:spec==='single'}]" @click="spec='single'">{{product.kind==='goods'?'1件':'1次'}}</text><text v-if="product.coursePrice!==undefined&&product.coursePrice!==null" :class="['spec',{selected:spec==='course'}]" @click="spec='course'">1疗程</text></view><view class="between"><text>选择购买数量</text><view class="quantity"><button :disabled="quantity<=1" @click="quantity--">−</button>{{quantity}}<button :disabled="quantity>=(selectedSku?selectedSku.stock:product.stock)||quantity>=99" @click="quantity++">+</button></view></view><button class="primary" @click="checkout">立即购买</button></view></view>
 </view>
</template>
<script>
import { api, go, toast, money } from '../common/api.js'
import { uploadAvatar } from '../common/avatar.js'
import { fallbackCatalogue } from '../common/fallback-catalogue.js'
import PackagePicker from './PackagePicker.vue'
import BookingAvailability from './BookingAvailability.vue'
import IncomeDashboard from './IncomeDashboard.vue'
import { version } from '../package.json'
import { packageSelectionError } from '../common/package-selection.js'
const titles={product:'商品详情',stores:'所有门店',gifts:'',login:'',profile:'个人信息',appointments:'我的预约',booking:'在线预约',activities:'活动专区',alliances:'百业联盟',checkout:'确认下单','order-detail':'订单详情',orders:'我的订单',addresses:'我的收件地址','address-edit':'添加地址',shares:'我分享的人',earnings:'收益明细',about:'关于我们',share:'我的分享码',legal:'服务条款',points:'我的积分',sign:'签到有礼',redemptions:'兑换记录'}
export default {
 components:{PackagePicker,BookingAvailability,IncomeDashboard},
 props:{page:String,query:{type:Object,default:()=>({})}},
 data(){return{incomeSummary:{},incomeRules:[],bookingReady:false,bookingRefresh:0,nativeDevice:false,statusBar:0,config:{},products:[],categories:[],stores:[],homeModules:[],me:{},rows:[],claimRows:[],orders:[],addresses:[],order:null,loading:false,error:'',formReady:false,authPrompted:false,shareImage:'',earningsRows:[],demoMode:false,paymentMode:'off',busy:false,retryTimer:null,clockNow:Date.now(),tab:0,mallCategory:'',sheet:false,packageSelection:{planId:'',groups:{}},packageLoadedFor:'',spec:'single',skuId:'',quantity:1,selectedStoreId:'',addressIndex:0,agreed:false,form:{},selectedGifts:[],times:['09:00','10:00','11:00','14:00','15:00','16:00','17:00','18:00'],mainTabs:[{page:'home',name:'首页'},{page:'mall',name:'商城'},{page:'discover',name:'发现'},{page:'mine',name:'我的'}],shortcuts:[{label:'体验卡',page:'gifts',query:'?type=trial',asset:'trial',color:'#fff'},{label:'贵宾卡',page:'gifts',query:'?type=vip',asset:'vip',color:'#f4ca72'},{label:'邀请码',page:'share',asset:'share',color:'#fff'}],menus:[['我的订单','orders'],['收件地址','addresses'],['我的分享','shares'],['我的收益','earnings'],['联系客服','contact'],['关于我们','about'],['退出登录','logout']],orderTabs:['全部','待付款','待使用','待取货','已完成','售后'],addressFields:[{key:'name',label:'收件人姓名',placeholder:'输入收件人姓名'},{key:'phone',label:'联系电话',placeholder:'输入联系电话'},{key:'city',label:'收件城市',placeholder:'输入省 / 市 / 区'},{key:'detail',label:'详细地址',placeholder:'输入详细地址'}]}},
 computed:{
  appVersion(){return version},
  isTab(){return ['home','mall','discover','mine'].includes(this.page)},
  bottomSpace(){return !this.isTab},
  title(){if(this.page==='product')return this.product?.name||'商品详情';if(this.page==='legal')return this.legalTitle;if(this.page==='gifts')return this.giftType==='trial'?'领取VIP体验商品':'领取尊享贵宾商品';return titles[this.page]||''},
  nativeNavStyle(){return this.nativeDevice?{'--nav-inset':this.statusBar+'px','--nav-height':(44+this.statusBar)+'px','--nav-center':(22+this.statusBar)+'px'}:{}},
  nativeBackStyle(){return this.nativeDevice?{top:(this.statusBar+22)+'px'}:{}},
  featuredCategoryId(){return (Array.isArray(this.categories)?this.categories:[]).find(x=>x&&x.enabled!==false&&String(x.name||'').includes('特色'))?.id||'category-featured'},
