age)&&!this.me.id){if(!this.authPrompted){this.authPrompted=true;go('login')}return}const endpoints={discover:'rewards',activities:'activities',alliances:'alliances',orders:'orders',addresses:'addresses',appointments:'appointments',booking:'appointments',shares:'shares',earnings:'earnings',points:'ledger',redemptions:'redemptions'};if(endpoints[this.page])this.rows=await api('/'+endpoints[this.page]);if(this.me.id&&['gifts','appointments','booking'].includes(this.page))this.claimRows=await api('/claims');if(this.page==='profile'&&!this.formReady){this.form={name:this.me.name,gender:this.me.gender,avatar:this.me.avatar};this.formReady=true}if(this.page==='address-edit'&&this.query.id&&!this.formReady){this.form=(await api('/addresses')).find(a=>a.id===this.query.id)||{};this.formReady=true}if(this.page==='checkout'){this.addresses=await api('/addresses');const selected=this.addresses.findIndex(a=>a.isDefault);if(selected>=0)this.addressIndex=selected}if(this.page==='order-detail'){this.order=await api('/orders/'+this.query.id);if(this.order.package)this.rows=await api('/appointments')}if(this.page==='booking'&&this.query.orderId)this.order=await api('/orders/'+this.query.orderId);if(this.page==='share')try{this.shareImage=(await api('/share-code')).image}catch(e){this.shareImage=''}if(this.page==='appointments')this.orders=await api('/orders');if(this.isPackage&&this.packageLoadedFor!==this.product.id){const draft=uni.getStorageSync('package-draft-'+this.product.id);this.packageSelection=draft&&this.product.packagePlans.some(p=>p.id===draft.planId)?draft:{planId:this.product.packagePlans[0].id,groups:{}};this.packageLoadedFor=this.product.id;this.quantity=1}}catch(e){const cached=uni.getStorageSync('catalogue');const data=cached&&cached.products&&cached.products.length?cached:fallbackCatalogue;Object.assign(this,JSON.parse(JSON.stringify(data)));this.error='网络连接暂时不稳定，当前显示已保存内容'}finally{this.loading=false}},checkAgreement(){if(!this.agreed)toast('请先阅读并同意协议')},checkout(){if(!this.product)return toast('商品不存在或已下架');if(this.product.skus?.length&&!this.selectedSku)return toast('请选择有库存的规格');if(this.quantity>(this.selectedSku?.stock??this.product.stock))return toast('所选规格库存不足');if(!this.me.id)return go('login');this.sheet=false;go('checkout','?id='+this.product.id+'&spec='+this.spec+'&quantity='+this.quantity+(this.skuId?'&skuId='+encodeURIComponent(this.skuId):''))},saveProfile(){return this.run(async()=>{await api('/me','PUT',this.form);toast('信息已保存');this.back()})},saveAddress(){return this.run(async()=>{await api('/addresses'+(this.query.id?'/'+this.query.id:''),this.query.id?'PUT':'POST',this.form);toast('地址已保存');this.back()})},async deleteAddress(a){const r=await uni.showModal({title:'删除地址',content:'确认删除此收货地址？'});if(r.confirm)this.run(async()=>{await api('/addresses/'+a.id,'DELETE');await this.refresh()})},createOrder(){if(!this.product)return toast('商品不存在或已下架');if(this.isPackage){const error=packageSelectionError(this.product,this.packageSelection);if(error)return toast(error);}if(!this.chosenStore.id)return toast('请选择有效门店');if(this.product.kind==='goods'&&!this.chosenAddress.id)return toast('请先选择收货地址');return this.run(async()=>{this.orderRequestKey=this.orderRequestKey||('order-'+Date.now()+'-'+Math.random().toString(36).slice(2));const o=await api('/orders','POST',{productId:this.product.id,skuId:this.skuId,spec:this.spec,quantity:this.quantity,storeId:this.chosenStore.id,addressId:this.chosenAddress.id,message:this.form.message,...(this.isPackage?{packageSelection:this.packageSelection}:{})},{'Idempotency-Key':this.orderRequestKey});this.orderRequestKey='';uni.redirectTo({url:'/pages/order-detail/index?id='+o.id})})},async cancelOrder(o){const r=await uni.showModal({title:'取消订单',content:'确认取消此订单？'});if(r.confirm)this.run(async()=>{await api('/orders/'+o.id+'/cancel','POST');await this.refresh()})},async pay(order){const store=this.recordStore(order||this.order||{});const r=await uni.showModal({title:'联系门店付款',content:'当前暂不支持微信在线支付，请联系'+(store.name||'服务门店')+'确认付款。门店确认收款后可预约，未付款订单2小时后自动取消。',confirmText:store.phone?'拨打电话':'知道了',showCancel:!!store.phone});if(r.confirm&&store.phone)this.call(store.phone)},selectGift(id){if(this.isGiftClaimed(id))return toast('该礼品已领取，可查看详情或预约使用');if(this.selectedGifts.includes(id))this.selectedGifts=this.selectedGifts.filter(x=>x!==id);else if(this.selectedGifts.length<this.config.maxGifts)this.selectedGifts.push(id);else toast('最多选择'+this.config.maxGifts+'件')},startGiftBooking(p){const c=this.giftClaims.find(c=>c.id===p.claimId)||this.giftClaimFor(p.id);if(!c)return toast('请先领取该礼品');const item=c.products?.find(x=>x.id===p.id);if(item?.useStatus!=='available')return toast(item?.useStatus==='booked'?'该礼品已预约，请在我的预约中查看':'该礼品已经使用');go('booking','?claimId='+c.id+'&productId='+p.id)},claim(){if(!this.me.id)return go('login');if(this.giftType==='vip'&&!this.me.invited)return toast('贵宾卡仅限受邀新用户领取');if(this.selectedGifts.length!==this.config.maxGifts)return toast('请选择领取'+this.config.maxGifts+'件商品');return this.run(async()=>{await api('/claims','POST',{productIds:this.selectedGifts,type:this.giftType});toast(this.giftType==='trial'?'领取成功，请选择项目预约':'领取成功');this.selectedGifts=[];await this.refresh()})},startBooking(){if(this.availableClaimGifts.length)return this.startGiftBooking(this.availableClaimGifts[0]);if(!this.availableOrders.length)return toast('暂无可预约服务，请先领取体验卡或购买服务项目');this.startOrderBooking(this.availableOrders[0])},setBookingSelection(value){this.form={date:value.date,time:value.time,staffId:value.staffId};this.bookingReady=value.ready},book(){this.clockNow=Date.now();if(!this.bookingAvailable)return toast('该项目暂不可预约，请查看使用状态');if(!this.bookingStoreEnabled)return toast('请选择营业中的门店，或联系商家确认');if(!this.bookingReady||Date.parse(this.form.date+'T'+this.form.time+':00+08:00')<=Date.now())return toast('请选择尚未开始的预约日期和时间');return this.run(async()=>{const payload={date:this.form.date,time:this.form.time,staffId:this.form.staffId||''};if(this.query.claimId){payload.claimId=this.query.claimId;payload.productId=this.query.productId;payload.storeId=this.chosenStore.id}else{payload.orderId=this.query.orderId;if(this.query.entitlementId)payload.entitlementId=this.query.entitlementId}try{await api('/appointments','POST',payload);toast('预约成功');this.back()}catch(e){this.bookingRefresh++;throw e}})},copy(v){if(v)uni.setClipboardData({data:v});else toast('请先登录')},call(phone){if(phone)uni.makePhoneCall({phoneNumber:phone})},contact(){uni.showModal({title:'联系客服',content:'门店电话：'+(this.stores[0]?.phone||''),confirmText:'拨打电话',success:r=>{if(r.confirm)this.call(this.stores[0]?.phone)}})}}
}
</script>


























